#include "emitters/artifacts.hpp"
#include "semantics/validate.hpp"
#include <sstream>
namespace bridgeabi::generator {
namespace { std::string stem(const interface_definition& d) { std::string value = d.name; for (auto& c : value) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c))); return value; } std::string ctype(const std::string& t) { if (t == "uint32") return "uint32_t"; if (t == "uint64") return "uint64_t"; if (t == "int32") return "int32_t"; if (t == "float32") return "float"; if (t == "float64") return "double"; if (t == "string") return "bridge_string_view"; if (t == "buffer") return "bridge_buffer_view"; return "void*"; } std::string hash(const std::string& value) { std::uint64_t h = 1469598103934665603ull; for (unsigned char c : value) { h ^= c; h *= 1099511628211ull; } std::ostringstream out; out << std::hex << h; return out.str(); } }
std::string fingerprint(const interface_definition& d) { std::string text = d.id + ":" + std::to_string(d.major) + "." + std::to_string(d.minor); for (const auto& m : d.methods) { text += ":" + std::to_string(m.id) + ":" + m.name + ":" + m.result_type + ":" + ownership_name(m.result_owner); for (const auto& p : m.parameters) text += ":" + p.type + ":" + ownership_name(p.owner) + (p.nullable ? "?" : ""); } return hash(text); }
artifact_set emit_artifacts(const interface_definition& d) { artifact_set a; const auto base = stem(d); const auto table = "bridge_" + base + "_v" + std::to_string(d.major); const auto fp = fingerprint(d); std::ostringstream c, host, plugin, descriptor, docs, compat;
c << "/* Generated by bridgeabi; ABI contract. */\n#pragma once\n#include <stdint.h>\n#include <stddef.h>\n#if defined(_WIN32)\n#define BRIDGE_CALL __cdecl\n#else\n#define BRIDGE_CALL\n#endif\ntypedef struct { const char* data; uint64_t size; uint32_t encoding; } bridge_string_view;\ntypedef struct { const uint8_t* data; uint64_t size; } bridge_buffer_view;\ntypedef struct { uint8_t* data; uint64_t size; void (BRIDGE_CALL *release)(void*, uint8_t*, uint64_t); void* release_context; } bridge_owned_buffer;\ntypedef struct { uint32_t code; } bridge_status;\ntypedef struct " << table << " { uint32_t struct_size; uint32_t abi_revision; void* instance;\n";
for (const auto& m : d.methods) { c << "  bridge_status (BRIDGE_CALL *" << m.name << ")(void* instance"; for (const auto& p : m.parameters) c << ", " << ctype(p.type) << " " << p.name; if (m.result_type != "void") c << ", " << ((m.result_type == "string" || m.result_type == "buffer") ? "bridge_owned_buffer" : ctype(m.result_type)) << "* result"; c << ");\n"; } c << "  void (BRIDGE_CALL *retain)(void*); void (BRIDGE_CALL *release)(void*); } " << table << ";\n"; a["c/" + base + "_abi.h"] = c.str();
host << "// Generated host proxy\n#pragma once\n#include <bridgeabi/abi.hpp>\n#include \"../c/" << base << "_abi.h\"\nnamespace bridge::generated { class " << d.name << " { const " << table << "* table_{}; public: explicit " << d.name << "(const " << table << "* table) : table_(table) {} explicit operator bool() const noexcept { return table_ && table_->struct_size >= sizeof(" << table << "); } }; }\n"; a["cpp/" + base + "_host.hpp"] = host.str();
plugin << "// Generated plugin adapter boundary\n#pragma once\n#include \"../c/" << base << "_abi.h\"\nnamespace bridge::generated { class " << d.name << "Implementation { public: virtual ~" << d.name << "Implementation() = default; /* Adapter implementations must catch all exceptions and return bridge_status. */ }; }\n"; a["cpp/" + base + "_plugin.hpp"] = plugin.str();
descriptor << "{\n  \"schemaVersion\": 1,\n  \"interface\": {\n    \"name\": \"" << d.name << "\",\n    \"namespace\": \"" << d.name_space << "\",\n    \"id\": \"" << d.id << "\",\n    \"version\": { \"major\": " << d.major << ", \"minor\": " << d.minor << " },\n    \"fingerprint\": \"" << fp << "\",\n    \"methods\": ["; for (std::size_t i=0;i<d.methods.size();++i) { const auto& m=d.methods[i]; descriptor << (i ? "," : "") << "\n      { \"id\": " << m.id << ", \"name\": \"" << m.name << "\", \"returnType\": \"" << m.result_type << "\", \"ownership\": \"" << ownership_name(m.result_owner) << "\" }"; } descriptor << "\n    ]\n  }\n}\n"; a["descriptors/" + base + ".json"] = descriptor.str();
docs << "# " << d.name << "\n\nInterface ID: `" << d.id << "`\n\nVersion: `" << d.major << "." << d.minor << "`\n\n## Methods\n"; for (const auto& m : d.methods) docs << "\n### `" << m.name << "`\n\nMethod ID: `" << m.id << "`\n"; a["docs/" + base + ".md"] = docs.str(); compat << "{\n  \"schemaVersion\": 1,\n  \"id\": \"" << d.id << "\",\n  \"version\": \"" << d.major << "." << d.minor << "\",\n  \"fingerprint\": \"" << fp << "\"\n}\n"; a["compatibility/" + base + ".compat.json"] = compat.str(); return a; }
}
